// convertPlaceholders converts SQLite-style ? placeholders to PostgreSQL-style $1, $2, etc.
// when running on PostgreSQL
func (t *SetupChecklistLine) convertPlaceholders(sql string, count int) string {
	if t.dbType != database.DBTypePostgres {
		return sql
	}
	result := sql
	for i := 1; i <= count; i++ {
		result = strings.Replace(result, "?", fmt.Sprintf("$%d", i), 1)
	}
	return result
}

// Get retrieves a record from the database by primary key (interface{} for generic API)
// For single primary key: pass the value directly (string, int, etc.)
// For composite keys: pass a map[string]interface{} with field names as keys
func (t *SetupChecklistLine) Get(primaryKey interface{}) bool {
	// Handle composite primary key (map[string]interface{})
	if pkMap, ok := primaryKey.(map[string]interface{}); ok {
		var line_noVal int
		if v, exists := pkMap["line_no"]; exists {
			switch val := v.(type) {
			case int:
				line_noVal = val
			case float64:
				line_noVal = int(val)
			case string:
				// the key part as text: the API's "CUSTOMER1,10000"
				if n, err := strconv.Atoi(strings.TrimSpace(val)); err == nil {
					line_noVal = n
				}
			}
		}
		return t.GetByPK(line_noVal)
	}
	// Handle single primary key (for tables with only one PK field)
	switch pk := primaryKey.(type) {
	case int:
		return t.GetByPK(pk)
	case float64:
		return t.GetByPK(int(pk))
	case string:
		var intVal int
		if _, err := fmt.Sscanf(pk, "%d", &intVal); err == nil {
			return t.GetByPK(intVal)
		}
	}

	fmt.Printf("Error: Invalid primary key type for Setup_Checklist_Line.Get: %T (use map for composite keys)\n", primaryKey)
	return false
}

// GetByPK retrieves a record by its typed primary key(s) - for direct typed access
func (t *SetupChecklistLine) GetByPK(line_no int) bool {
	tableName := fmt.Sprintf("%s$%s", t.company, SetupChecklistLineTableName)
	var line_noVal int
	var table_idVal int
	var table_nameNull sql.NullString
	var copying_availableBool sql.NullBool
	var page_idVal int
	var page_nameNull sql.NullString
	var starting_dateNull sql.NullString
	var ending_dateNull sql.NullString
	var responsible_idNull sql.NullString
	var statusInt int
	var application_area_idVal int

	// Collect arguments for query
	args := []interface{}{
		line_no,
	}

	// Build SQL with placeholders
	sqlStr := fmt.Sprintf(`SELECT line_no, table_id, table_name, copying_available, page_id, page_name, starting_date, ending_date, responsible_id, status, application_area_id FROM "%s" WHERE 1=1 AND line_no = ?`, tableName)

	// Convert placeholders for PostgreSQL
	sqlStr = t.convertPlaceholders(sqlStr, len(args))
	sqlStr += t.forUpdate()

	err := t.exec().QueryRow(sqlStr, args...).Scan(
		&line_noVal,
		&table_idVal,
		&table_nameNull,
		&copying_availableBool,
		&page_idVal,
		&page_nameNull,
		&starting_dateNull,
		&ending_dateNull,
		&responsible_idNull,
		&statusInt,
		&application_area_idVal,
	)

	if err != nil {
		if err == sql.ErrNoRows {
			// Record not found - this is not an error, just return false
			return false
		}
		// Actual database error
		fmt.Printf("Error: Failed to get Setup_Checklist_Line: %v\n", err)
		return false
	}

	// Populate fields
	t.Line_no = line_noVal
	t.Table_id = table_idVal
	t.Table_name = types.NewText(table_nameNull.String)
	t.Copying_available = copying_availableBool.Bool
	t.Page_id = page_idVal
	t.Page_name = types.NewText(page_nameNull.String)
	t.Starting_date, _ = types.NewDateFromString(starting_dateNull.String)
	t.Ending_date, _ = types.NewDateFromString(ending_dateNull.String)
	t.Responsible_id = types.NewCode(responsible_idNull.String)
	t.Status = SetupChecklistLineStatus(statusInt)
	t.Application_area_id = application_area_idVal

	// Store old values for field tracking
	t.StoreOldValues()

	return true
}

// Insert inserts the record into the database
func (t *SetupChecklistLine) Insert(runTrigger bool) bool {
	// OnInsert trigger of the business logic, then the field checks of the definition
	t.triggerErr = nil
	if runTrigger {
		if err := t.runOnInsert(); err != nil {
			fmt.Printf("Error: OnInsert trigger failed: %v\n", err)
			t.triggerErr = err
			return false
		}
	}
	tableName := fmt.Sprintf("%s$%s", t.company, SetupChecklistLineTableName)

	// Collect arguments for INSERT
	args := []interface{}{
		t.Line_no,
		t.Table_id,
		t.Table_name,
		t.Copying_available,
		t.Page_id,
		t.Page_name,
		t.Starting_date,
		t.Ending_date,
		t.Responsible_id,
		t.Status,
		t.Application_area_id,
	}

	// Build SQL with placeholders. A taken key inserts nothing (ON CONFLICT … DO NOTHING) instead
	// of failing: on PostgreSQL a failed INSERT would abort the transaction
	sqlStr := fmt.Sprintf(`INSERT INTO "%s" (line_no, table_id, table_name, copying_available, page_id, page_name, starting_date, ending_date, responsible_id, status, application_area_id) VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?) ON CONFLICT (line_no) DO NOTHING`, tableName)

	// Convert placeholders for PostgreSQL
	sqlStr = t.convertPlaceholders(sqlStr, len(args))

	result, err := t.exec().Exec(sqlStr, args...)
	if err != nil {
		fmt.Printf("Error: Failed to insert Setup_Checklist_Line: %v\n", err)
		return false
	}
	// The key is taken (INSERT fails in the classic way: "<Table> <key> already exists")
	if n, err := result.RowsAffected(); err == nil && n == 0 {
		_, key := t.recordKey()
		t.triggerErr = apperrors.TableRecordExists(SetupChecklistLineTableName, key)
		return false
	}
	// The record as written: its xRec from now on (a following Modify or Rename compares with it)
	t.StoreOldValues()
	return true
}

// InsertAll inserts records in bulk (demo data, imports): multi-row INSERT statements, one
// round trip per batch instead of one per record. With runTrigger every record's OnInsert
// trigger runs first, as Insert(true) would; the first failure stops before anything is
// written. Records are written with the receiver's database and company. Errors are
// *tables.BatchInsertError (Index = the record in records). Use it in a transaction: a
// failed batch leaves the earlier batches written.
func (t *SetupChecklistLine) InsertAll(records []*SetupChecklistLine, runTrigger bool) error {
	rows := make([][]interface{}, 0, len(records))
	for i, r := range records {
		r.triggerErr = nil
		if runTrigger {
			if err := r.runOnInsert(); err != nil {
				r.triggerErr = err
				return &tables.BatchInsertError{Index: i, Trigger: true, Err: err}
			}
		}
		rows = append(rows, []interface{}{
			r.Line_no,
			r.Table_id,
			r.Table_name,
			r.Copying_available,
			r.Page_id,
			r.Page_name,
			r.Starting_date,
			r.Ending_date,
			r.Responsible_id,
			r.Status,
			r.Application_area_id,
		})
	}
	tableName := fmt.Sprintf("%s$%s", t.company, SetupChecklistLineTableName)
	columns := []string{"line_no", "table_id", "table_name", "copying_available", "page_id", "page_name", "starting_date", "ending_date", "responsible_id", "status", "application_area_id"}
	return tables.InsertRows(t.exec(), t.dbType, tableName, columns, rows)
}

// Modify updates the record in the database
func (t *SetupChecklistLine) Modify(runTrigger bool) bool {
	// OnModify trigger of the business logic, then the field checks of the definition
	t.triggerErr = nil
	if runTrigger {
		if err := t.runOnModify(); err != nil {
			fmt.Printf("Error: OnModify trigger failed: %v\n", err)
			t.triggerErr = err
			return false
		}
	}
	// A changed primary key is a rename: run the OnRename trigger
	// before it is written; xRec values are available through OldValue
	keyChanged := false
	if t.oldValues != nil {
		if t.hasFieldChanged("line_no") {
			keyChanged = true
		}
	}
	if runTrigger && keyChanged {
		if err := t.runOnRename(); err != nil {
			fmt.Printf("Error: OnRename trigger failed: %v\n", err)
			t.triggerErr = err
			return false
		}
	}
	tableName := fmt.Sprintf("%s$%s", t.company, SetupChecklistLineTableName)

	// Build dynamic SQL based on field tracking
	var setClauses []string
	var values []interface{}

	// If we have old values (loaded from Get), only update changed fields.
	// Changed primary key fields are renamed in place (Rename): they are SET to the
	// new value while the WHERE clause matches the old one.
	if t.oldValues != nil {
		if t.hasFieldChanged("line_no") {
			setClauses = append(setClauses, "line_no = ?")
			values = append(values, t.Line_no)
		}
		if t.hasFieldChanged("table_id") {
			setClauses = append(setClauses, "table_id = ?")
			values = append(values, t.Table_id)
		}
		if t.hasFieldChanged("table_name") {
			setClauses = append(setClauses, "table_name = ?")
			values = append(values, t.Table_name)
		}
		if t.hasFieldChanged("copying_available") {
			setClauses = append(setClauses, "copying_available = ?")
			values = append(values, t.Copying_available)
		}
		if t.hasFieldChanged("page_id") {
			setClauses = append(setClauses, "page_id = ?")
			values = append(values, t.Page_id)
		}
		if t.hasFieldChanged("page_name") {
			setClauses = append(setClauses, "page_name = ?")
			values = append(values, t.Page_name)
		}
		if t.hasFieldChanged("starting_date") {
			setClauses = append(setClauses, "starting_date = ?")
			values = append(values, t.Starting_date)
		}
		if t.hasFieldChanged("ending_date") {
			setClauses = append(setClauses, "ending_date = ?")
			values = append(values, t.Ending_date)
		}
		if t.hasFieldChanged("responsible_id") {
			setClauses = append(setClauses, "responsible_id = ?")
			values = append(values, t.Responsible_id)
		}
		if t.hasFieldChanged("status") {
			setClauses = append(setClauses, "status = ?")
			values = append(values, t.Status)
		}
		if t.hasFieldChanged("application_area_id") {
			setClauses = append(setClauses, "application_area_id = ?")
			values = append(values, t.Application_area_id)
		}

		// If nothing changed, skip update
		if len(setClauses) == 0 {
			return true // No changes, success
		}
	} else {
		// No old values (fresh record), update all fields
		setClauses = append(setClauses, "table_id = ?")
		values = append(values, t.Table_id)
		setClauses = append(setClauses, "table_name = ?")
		values = append(values, t.Table_name)
		setClauses = append(setClauses, "copying_available = ?")
		values = append(values, t.Copying_available)
		setClauses = append(setClauses, "page_id = ?")
		values = append(values, t.Page_id)
		setClauses = append(setClauses, "page_name = ?")
		values = append(values, t.Page_name)
		setClauses = append(setClauses, "starting_date = ?")
		values = append(values, t.Starting_date)
		setClauses = append(setClauses, "ending_date = ?")
		values = append(values, t.Ending_date)
		setClauses = append(setClauses, "responsible_id = ?")
		values = append(values, t.Responsible_id)
		setClauses = append(setClauses, "status = ?")
		values = append(values, t.Status)
		setClauses = append(setClauses, "application_area_id = ?")
		values = append(values, t.Application_area_id)
	}

	// Add WHERE clause value (primary key as loaded, so a renamed key still matches)
	if old, ok := t.oldValues["line_no"]; ok {
		values = append(values, old)
	} else {
		values = append(values, t.Line_no)
	}

	// Build and execute SQL
	sqlStr := fmt.Sprintf(`UPDATE "%s" SET %s WHERE 1=1 AND line_no = ?`,
		tableName,
		strings.Join(setClauses, ", "),
	)

	// Convert placeholders for PostgreSQL
	sqlStr = t.convertPlaceholders(sqlStr, len(values))

	_, err := t.exec().Exec(sqlStr, values...)
	if err != nil {
		fmt.Printf("Error: Failed to modify Setup_Checklist_Line: %v\n", err)
		return false
	}
	// The stored record now matches the current values (including a renamed key)
	if t.oldValues != nil {
		t.StoreOldValues()
	}
	return true
}

// hasFieldChanged checks if a field value has changed from oldValues
func (t *SetupChecklistLine) hasFieldChanged(fieldName string) bool {
	if t.oldValues == nil {
		return true // No old values, assume changed
	}

	oldValue, exists := t.oldValues[fieldName]
	if !exists {
		return true // Field not in old values, assume changed
	}
	_ = oldValue // Suppress unused variable when all fields are PKs

	// Compare old vs new value based on field name (with type assertion)
	switch fieldName {
	case "line_no":
		if old, ok := oldValue.(int); ok {
			return t.Line_no != old
		}
		return true // Type mismatch, assume changed
	case "table_id":
		if old, ok := oldValue.(int); ok {
			return t.Table_id != old
		}
		return true // Type mismatch, assume changed
	case "table_name":
		if old, ok := oldValue.(types.Text); ok {
			return !t.Table_name.Equal(old)
		}
	case "copying_available":
		if old, ok := oldValue.(bool); ok {
			return t.Copying_available != old
		}
		return true // Type mismatch, assume changed
	case "page_id":
		if old, ok := oldValue.(int); ok {
			return t.Page_id != old
		}
		return true // Type mismatch, assume changed
	case "page_name":
		if old, ok := oldValue.(types.Text); ok {
			return !t.Page_name.Equal(old)
		}
	case "starting_date":
		if old, ok := oldValue.(types.Date); ok {
			return !t.Starting_date.Equal(old)
		}
	case "ending_date":
		if old, ok := oldValue.(types.Date); ok {
			return !t.Ending_date.Equal(old)
		}
	case "responsible_id":
		if old, ok := oldValue.(types.Code); ok {
			return !t.Responsible_id.Equal(old)
		}
	case "status":
		if old, ok := oldValue.(SetupChecklistLineStatus); ok {
			return t.Status != old
		}
	case "application_area_id":
		if old, ok := oldValue.(int); ok {
			return t.Application_area_id != old
		}
		return true // Type mismatch, assume changed
	}

	return false
}

